"kind": "propose",
"summary": "The new version (4.2.0) is using more CPU than the limit, causing throttling and readiness probe failures. Increase the CPU limit for the 'api' container.",
"hypotheses": [
  {
    "root_cause_class": "new_version_uses_more_cpu",
    "summary": "The new version uses more CPU than the limit, causing throttling.",
    "supporting": ["ev-container_cpu", "ev-revision_health", "ev-rollout_history"],
    "contradicting": [],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "api": {
        "requests": {
          "cpu": "250m"
        },
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "Raise the CPU limit to 750m to prevent throttling and improve performance.",
  "rationale": "The new version (4.2.0) is using nearly the full CPU limit (0.495/0.5) and is throttled 64% of the time. The previous revision (1) had much lower throttling (8%). Increasing the CPU limit to 750m should alleviate the throttling and resolve the readiness probe failures.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-revision_health", "ev-rollout_history"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit", "rollout_changed_the_app", "throttling_came_with_rollout", "earlier_revision_healthy"]
}
}
